data class AccountSession(val uid:String,val email:String,val token:String)
data class AccountProfile(val uid:String,val name:String,val username:String,val bio:String,val photo:String,val cover:String,val color:String,val isPublic:Boolean,val frameId:String,val role:String,val followers:Int=0,val following:Int=0,val comments:Int=0)
class AccountStore(c:Context){private val p=c.getSharedPreferences("mp_account",Context.MODE_PRIVATE);fun session():AccountSession?{val u=p.getString("uid","").orEmpty();val t=p.getString("token","").orEmpty();return if(u.isBlank()||t.isBlank())null else AccountSession(u,p.getString("email","").orEmpty(),t)};fun save(s:AccountSession){p.edit().putString("uid",s.uid).putString("email",s.email).putString("token",s.token).apply()};fun clear(){p.edit().clear().apply()}}
class AccountRepository{private val base="https://nnnsss-23f2f-default-rtdb.firebaseio.com";private val key="AIzaSyAbpqQIxWuEnFolv3lNjNDoPKTGm0mtrxU";private fun e(v:String)=URLEncoder.encode(v,"UTF-8")
 suspend fun signIn(email:String,password:String)=withContext(Dispatchers.IO){val x=req("https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=$key","POST",JSONObject().put("email",email.trim()).put("password",password).put("returnSecureToken",true).toString());AccountSession(x.getString("localId"),x.optString("email",email),x.getString("idToken"))}
 suspend fun profile(s:AccountSession)=withContext(Dispatchers.IO){val u=req("$base/usuarios/${e(s.uid)}.json?auth=${e(s.token)}");val pub=runCatching{req("$base/perfisPublicos/${e(s.uid)}.json")}.getOrDefault(JSONObject());fun v(vararg k:String)=k.firstNotNullOfOrNull{u.optString(it).takeIf(String::isNotBlank)}?:k.firstNotNullOfOrNull{pub.optString(it).takeIf(String::isNotBlank)}?:"";val followers=count("$base/seguidores/${e(s.uid)}.json?auth=${e(s.token)}");val following=count("$base/seguindo/${e(s.uid)}.json?auth=${e(s.token)}");val comments=countOwn(s.uid);AccountProfile(s.uid,v("nome","name").ifBlank{"Leitor MP SCAN"},v("nomeUsuario","username"),v("bio"),v("foto","photo"),v("capaPerfil","cover"),v("corPerfil","color").ifBlank{"#8d2bff"},if(u.has("publico"))u.optBoolean("publico") else pub.optBoolean("publico",true),v("molduraComentarioId"),v("papel","role").ifBlank{"Usuário"},followers,following,comments)}
 suspend fun saveProfile(s:AccountSession,p:AccountProfile)=withContext(Dispatchers.IO){val x=JSONObject().put("nome",p.name).put("nomeUsuario",p.username.removePrefix("@")).put("bio",p.bio).put("foto",p.photo).put("capaPerfil",p.cover).put("corPerfil",p.color).put("publico",p.isPublic).put("molduraComentarioId",p.frameId).put("atualizadoEm",System.currentTimeMillis());req("$base/usuarios/${e(s.uid)}.json?auth=${e(s.token)}","PATCH",x.toString());val pub=JSONObject(x.toString()).put("uid",s.uid);if(!p.isPublic){pub.remove("bio");pub.remove("capaPerfil")};req("$base/perfisPublicos/${e(s.uid)}.json?auth=${e(s.token)}","PUT",pub.toString());req("$base/identidadesComentarios/${e(s.uid)}.json?auth=${e(s.token)}","PUT",JSONObject().put("uid",s.uid).put("nome",p.name).put("nomeUsuario",p.username.removePrefix("@")).put("foto",p.photo).put("molduraComentarioId",p.frameId).toString())}
 private fun count(url:String)=runCatching{req(url).length()}.getOrDefault(0)
 private fun countOwn(uid:String):Int{val root=runCatching{req("$base/comentariosV1.json")}.getOrDefault(JSONObject());var n=0;fun walk(x:JSONObject){x.keys().forEach{k->x.optJSONObject(k)?.let{v->if(v.optString("uid")==uid)n++;walk(v)}}};walk(root);return n}
 fun request(url:String,m:String="GET",body:String?=null)=req(url,m,body)
 private fun req(url:String,m:String="GET",body:String?=null):JSONObject{val c=URL(url).openConnection() as HttpURLConnection;c.requestMethod=m;c.connectTimeout=15000;c.readTimeout=25000;c.setRequestProperty("Content-Type","application/json");if(body!=null){c.doOutput=true;c.outputStream.use{it.write(body.toByteArray())}};val ok=c.responseCode in 200..299;val t=(if(ok)c.inputStream else c.errorStream)?.bufferedReader()?.use{it.readText()}.orEmpty();c.disconnect();if(!ok)error(if("INVALID_PASSWORD" in t||"EMAIL_NOT_FOUND" in t)"E-mail ou senha incorretos." else if("TOKEN_EXPIRED" in t)"Sua sessão expirou. Entre novamente." else "Não foi possível conectar.");return if(t.isBlank()||t=="null")JSONObject()else JSONObject(t)}}